/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// Parameter to include number of tasks.
/// </summary>
/// <param name = "_numOfTasks">NumOfThreads</param>
/// <returns>NumOfThreads</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute('@MET:VendOpenItemsTasks'),
    SysOperationDisplayOrderAttribute('1')
]
public METNumOfTasks getNumOfTasks(METNumOfTasks _numOfTasks = numOfTasks)
{
    numOfTasks = _numOfTasks;
    if(numOfTasks <= 0)
    {
        numOfTasks = 1; 
    }
    return numOfTasks;
}

/// <summary>
/// Parameter to include legal entity of vendor lookup.
/// </summary>
/// <param name = "_vendLegalEntityId">Vendor legal entityId</param>
/// <returns>Value of type LegalEntityDataAreaId</returns>
[
    DataMemberAttribute,
    SysOperationDisplayOrderAttribute('2')
]
public LegalEntityDataAreaId getVendLegalEntityId(LegalEntityDataAreaId _vendLegalEntityId = vendLegalEntityId)
{
    vendLegalEntityId = _vendLegalEntityId;
    return vendLegalEntityId;
}

/// <summary>
/// Parameter to specify vendor account number.
/// </summary>
/// <param name = "_vendAccountNum">Vendor account number</param>
/// <returns>Value of type VendAccount</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute('@SYS14048'),
    SysOperationDisplayOrderAttribute('3')
]
public AccountNum getVendAccountNum(AccountNum _vendAccountNum = vendAccountNum)
{
    vendAccountNum = _vendAccountNum;
    return vendAccountNum;
}

/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// </summary>
/// <param name = "_recList">RecID list</param>
/// <returns>list of RecIDs</returns>
[
    DataMemberAttribute,
    AifCollectionTypeAttribute(identifierStr(_recList), Types::Int64),
    SysOperationLabelAttribute('@MET:VendOpenItemsRecList')
]
public List getRecList(List _recList = recList)
{
    recList = _recList;
    return recList;
}
